import{_ as o,a0 as C,w as p,s as u,ao as n,I as i,x as l,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"CI/CD 管道是什么？ | LCTT x X-CMD","titleTemplate":false,"description":"CI/CD 管道是什么？ | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CI/CD 管道是什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CI/CD 管道是什么？ | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210614 What is a CI-CD pipeline","title":"CI/CD 管道是什么？","tag":"202107","desc":""},"relativePath":"202107/20210614 What is a CI-CD pipeline.md","filePath":"[post].md"}'),a={name:"202107/20210614 What is a CI-CD pipeline.md"};function d(D,t,m,I,f,b){const e=C("Link");return p(),u("div",null,[t[28]||(t[28]=n('<h1 id="ci-cd-管道是什么" tabindex="-1">CI/CD 管道是什么？ <a class="header-anchor" href="#ci-cd-管道是什么" aria-label="Permalink to “CI/CD 管道是什么？”">​</a></h1><blockquote><p>你如何定义持续集成/持续部署管道取决于你组织的要求。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/plumbing_pipes_tutorial_how_behind_scenes.png?itok=F2Z8OJV1" alt="Plumbing tubes in many directions" title="Plumbing tubes in many directions"></p><p><ruby>持续集成<rt>continuous integration</rt></ruby>/<ruby>持续部署<rt>continuous deployment</rt></ruby>（CI/CD）管道是每个 DevOps 计划的基础。 CI/CD 管道打破了传统的开发孤岛，使开发和运营团队能够在整个软件开发生命周期中进行协作。</p>',4)),i("p",null,[t[1]||(t[1]=l("更好的是，转向 DevOps 和 CI/CD 管道可以帮助你的组织以更高的速度更安全地 ",-1)),r(e,{href:"https://techbeacon.com/devops/5-reasons-why-cicd-vital-your-organizations-value-stream"},{default:s(()=>[...t[0]||(t[0]=[l("交付软件",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[29]||(t[29]=n('<h3 id="拆解-ci-cd-管道" tabindex="-1">拆解 CI/CD 管道 <a class="header-anchor" href="#拆解-ci-cd-管道" aria-label="Permalink to “拆解 CI/CD 管道”">​</a></h3><p>CI/CD 管道有很多定义，所以我总是建议组织定义自己的 CI/CD 管道版本和其他 DevOps 概念，而不是使用其他人的。开源 CI/CD 工具为你提供构建满足组织要求的 CI/CD 管道的自由和选择。</p><p>形成 CI/CD 管道的阶段是将不同的任务子集分组为 <em>管道阶段</em>。典型的管道阶段包括：</p><ul><li><strong>构建</strong>：开发人员编译应用程序代码。</li><li><strong>测试</strong>：质量保证（QA）团队使用自动化测试工具和策略测试应用程序代码。</li><li><strong>发布</strong>：开发团队将应用程序代码交付到代码库。</li><li><strong>部署</strong>：DevOps 团队将应用程序代码分阶段投入生产。</li><li><strong>安全性和合规性</strong>：QA 团队根据项目要求验证构建。这是组织部署容器扫描工具的阶段，这些工具根据<ruby>常见漏洞和暴露<rt>Common Vulnerabilities and Exposures</rt></ruby>（CVE）检查容器镜像的质量。</li></ul><p>这些是 CI/CD 管道的标准阶段，但一些组织调整 CI/CD 管道模型以满足他们的要求。例如，为医疗保健市场构建应用程序的组织，具有严格的合规性标准，可以在整个工具链中分发测试、验证和合规性门槛。</p>',5)),i("p",null,[t[5]||(t[5]=l("其他示例可能是依赖于具有开源软件（OSS）的复杂软件供应链的组织。商业组件可能会设立一个门槛，开发团队成员可以在其中为 OSS 包生成 ",-1)),i("ruby",null,[r(e,{href:"https://www.ntia.gov/SBOM"},{default:s(()=>[...t[3]||(t[3]=[l("软件物料清单",-1)])]),_:1}),t[4]||(t[4]=i("rt",null,"software bill of materials",-1))]),t[6]||(t[6]=l("（SBOM），或者外部商业软件供应商必须将 SBOM 作为其合同可交付成果的一部分进行交付。",-1))]),t[30]||(t[30]=n('<h3 id="ci-cd-管道的障碍" tabindex="-1">CI/CD 管道的障碍 <a class="header-anchor" href="#ci-cd-管道的障碍" aria-label="Permalink to “CI/CD 管道的障碍”">​</a></h3><p>实施 CI/CD 管道会改变团队的流程和文化。尽管许多开发人员愿意接受某些任务和测试的自动化，但人员可能成为采用 CI/CD 的障碍。</p><p>从瀑布式流程转向 CI/CD 可能会动摇某些组织中基本的和隐含的权力结构。由于 CI/CD 管道提高了软件交付速度，旧手动流程的“守门人”可能会受到这种变化的威胁。</p><h3 id="整合机会" tabindex="-1">整合机会 <a class="header-anchor" href="#整合机会" aria-label="Permalink to “整合机会”">​</a></h3><p>随着你在文化、流程和工具中达到更高的 DevOps 成熟度水平，包含 CI/CD 工具链的工具的开源根源为一些激动人心的集成创造了机会。</p><p>分析公司 Forrester 在 2020 年预测，<ruby>即时学习<rt>just-in-time learning</rt></ruby>将加入 CI/CD 管道。如果你考虑一下，会发现这是有道理的。在当前远程工作的时代，甚至对于新员工的远程入职，这更有意义。例如，组织可以将文档 wiki 与内部流程文档集成到其管道中。</p>',6)),i("p",null,[t[8]||(t[8]=l("更雄心勃勃的组织可以将学习管理系统（LMS）（例如 ",-1)),r(e,{href:"https://moodle.org/"},{default:s(()=>[...t[7]||(t[7]=[l("Moodle",-1)])]),_:1}),t[9]||(t[9]=l("）集成到其 CI/CD 管道中。它可以使用 LMS 发布有关新 DevOps 工具链功能的简短视频，开发人员在加入时或在整个管道中更新工具时需要学习这些功能。",-1))]),i("p",null,[t[11]||(t[11]=l("一些组织正在将群聊和其他协作工具直接集成到他们的 CI/CD 管道中。聊天平台提供警报并支持团队之间的协作和沟通。将 Mattermost、Rocket.Chat 或其他 ",-1)),r(e,{href:"https://opensource.com/alternatives/slack"},{default:s(()=>[...t[10]||(t[10]=[l("企业聊天",-1)])]),_:1}),t[12]||(t[12]=l(" 平台集成到你的 CI/CD 管道中需要预先规划和分析，以确保管道用户不会被警报淹没。",-1))]),t[31]||(t[31]=i("p",null,"另一个需要探索的集成机会是将分析和高级报告构建到你的 CI/CD 管道中。这有助于你利用通过管道传输的数据。",-1)),t[32]||(t[32]=i("h3",{id:"总结",tabindex:"-1"},[l("总结 "),i("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[33]||(t[33]=i("p",null,"CI/CD 管道是 DevOps 的基础。开源使其能够适应并灵活地满足你在 DevOps 之旅中实施的运营变更所产生的新需求。",-1)),t[34]||(t[34]=i("p",null,"我希望看到对统一 DevOps 平台趋势的开源响应，在这种趋势中，组织寻求端到端的 CI/CD 解决方案。这种解决方案的要素就在那里。毕竟，GitLab 和 GitHub 将他们的平台追溯到开源根源。",-1)),t[35]||(t[35]=i("p",null,"最后，不要忘记每一个成功的 CI/CD 工具链背后的教育和外展。记录你的工具链和相关流程将改善开发人员入职和持续的 DevOps 团队培训。",-1)),t[36]||(t[36]=i("p",null,"你和你的组织如何定义你的 CI/CD 工具链？请在评论中分享你的反馈。",-1)),t[37]||(t[37]=i("hr",null,null,-1)),i("p",null,[t[14]||(t[14]=l("via: ",-1)),r(e,{href:"https://opensource.com/article/21/6/what-cicd-pipeline"},{default:s(()=>[...t[13]||(t[13]=[l("https://opensource.com/article/21/6/what-cicd-pipeline",-1)])]),_:1})]),i("p",null,[t[19]||(t[19]=l("作者：",-1)),r(e,{href:"https://opensource.com/users/willkelly"},{default:s(()=>[...t[15]||(t[15]=[l("Will Kelly",-1)])]),_:1}),t[20]||(t[20]=l(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[16]||(t[16]=[l("lujun9972",-1)])]),_:1}),t[21]||(t[21]=l(" 译者：",-1)),r(e,{href:"https://github.com/baddate"},{default:s(()=>[...t[17]||(t[17]=[l("baddate",-1)])]),_:1}),t[22]||(t[22]=l(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[18]||(t[18]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=l("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[23]||(t[23]=[l("LCTT",-1)])]),_:1}),t[26]||(t[26]=l(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:s(()=>[...t[24]||(t[24]=[l("Linux中国",-1)])]),_:1}),t[27]||(t[27]=l(" 荣誉推出",-1))])])}const v=o(a,[["render",d]]);export{S as __pageData,v as default};
